export const DURATION=180;
export const EVENTS=[
 {at:0,who:'Lage',text:'Du bist Lars Koch. Du fliegst neben dem Passagierflugzeug und blickst seitlich durch die Cockpithaube. Nach der Einsatzmeldung sind 164 Menschen an Bord. Als mögliches Ziel wird ein Stadion mit 70’000 Menschen genannt. Du kannst nicht sehen, was in der Kabine geschieht.',scene:'begleitung'},
 {at:25,who:'Innerer Monolog · erfunden',text:'Ich sehe eine Maschine. Hinter diesen Fenstern sitzen Menschen. Wer weiss dort gerade mehr als ich?',scene:'kontakt'},
 {at:55,who:'Lauterbach · erfundener Funkdialog',text:'Deine Anfrage wird weitergegeben. Die Entscheidung liegt nicht allein bei mir. Radtke trägt die Frage an den Verteidigungsminister heran.'},
 {at:85,who:'Lauterbach · erfundener Funkdialog',text:'Rückmeldung aus der Befehlskette: Keine Freigabe. Das Flugzeug darf nicht abgeschossen werden. Der Minister hat den Abschuss abgelehnt.',scene:'befehl'},
 {at:120,who:'Beobachtung · simuliert',text:'Die Maschine geht in einen sichtbaren Sinkflug über. Du deutest dies als Zuspitzung der Gefahr für das Stadion. Der Sinkflug allein zeigt dir nicht, wer gerade die Kontrolle hat.',scene:'sinkflug'},
 {at:150,who:'Innerer Monolog · erfunden',text:'Die Zeit drängt. Ich wünsche mir Gewissheit. Aber wird etwas dadurch sicher, dass ich es nicht länger offenlassen kann?',scene:'nahsicht'},
 {at:180,who:'Entscheidungspunkt',text:'Die simulierte Entscheidungszeit ist abgelaufen. Das Bild hält an. Es wird keine Entscheidung für dich getroffen. Was willst du verantworten?',scene:'entscheidung'}
];
export const CALLS={
 cockpit:{label:'Cockpit / Entführer ansprechen',own:'Ich versuche, die Person im Cockpit des Passagierflugzeugs anzusprechen. Wer führt die Maschine? Können Sie mich hören?',reply:'Keine verständliche Antwort. Du weisst nicht, ob die Übertragung gehört wurde, ob jemand antworten kann oder wer im Cockpit die Kontrolle hat.'},
 lauterbach:{label:'Lauterbach um Entscheidung bitten',own:'Lauterbach, ich brauche eine Entscheidung. Wie lautet der Befehl?',reply:'Lauterbach: Ich gebe deine Frage weiter. Radtke ist eingeschaltet; die Entscheidung wird an den Verteidigungsminister herangetragen.'},
 kabine:{label:'Nach Menschen in der Kabine fragen',own:'Gibt es Informationen von Besatzung oder Passagieren? Versucht jemand einzugreifen?',reply:'Lauterbach: Mir liegt dazu keine belastbare Rückmeldung vor. Keine Nachricht bedeutet nicht, dass dort niemand handelt.'},
 stadion:{label:'Nach Räumung des Stadions fragen',own:'Was ist mit dem Stadion? Werden die Menschen herausgebracht?',reply:'Lauterbach: Ich kann dir keine bestätigte Räumung melden. Die Information, die du brauchst, liegt mir jetzt nicht vor.'}
};
export function createState(){return {elapsed:0,eventIndex:0,log:[],pending:[],called:[],ended:false,choice:null};}
export function advance(s,seconds){if(s.ended)return [];s.elapsed=Math.min(DURATION,s.elapsed+Math.max(0,seconds));const added=[];while(s.eventIndex<EVENTS.length&&EVENTS[s.eventIndex].at<=s.elapsed){const e=EVENTS[s.eventIndex++];added.push({...e});}for(const p of s.pending.filter(p=>p.at<=s.elapsed))added.push(p);s.pending=s.pending.filter(p=>p.at>s.elapsed);added.sort((a,b)=>a.at-b.at);s.log.push(...added);return added;}
export function call(s,id){if(s.ended||s.elapsed>=DURATION||!CALLS[id]||s.called.includes(id))return false;s.called.push(id);s.log.push({at:s.elapsed,who:'Du · erfundener Funkdialog',text:CALLS[id].own});s.pending.push({at:Math.min(DURATION,s.elapsed+7),who:'Funk · erfunden',text:id==='lauterbach'&&s.elapsed>=85?'Lauterbach: Der Nicht-Abschussbefehl gilt. Es liegt keine neue Freigabe vor.':CALLS[id].reply});return true;}
export function decide(s,choice){if(s.ended||!['schiessen','nicht','offen'].includes(choice))return false;s.ended=true;s.choice=choice;s.log.push({at:s.elapsed,who:'Deine Entscheidung',text:{schiessen:'Abschuss entscheiden',nicht:'Nicht schiessen',offen:'Entscheidung bewusst offenlassen'}[choice]});return true;}

const norm=text=>text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss');
export function radioReply(text,elapsed){
 const t=norm(text);
 if(/entfuhrer|airbus|lufthansa|passagierflugzeug|zivilmaschine|cockpit/.test(t)&&!/lauterbach/.test(t))return {who:'Passagierflugzeug · Funkversuch',text:'[Rauschen. Keine verständliche Antwort.] Du kannst nicht feststellen, wer dich hört oder weshalb niemand antwortet.'};
 if(/sicht|fenster|sehen|blick|zeichen|neben|position/.test(t))return {who:'Beobachtung · simuliert',text:'Du fliegst neben der Maschine. Durch die Fenster erkennst du keine eindeutige Reaktion. Was in der Kabine geschieht, bleibt dir verborgen. Die Seite der Begleitung ist hier eine bildnerische Setzung; Koch nennt sie an dieser Textstelle nicht.'};
 if(/stadion|raum|evak|zuschauer/.test(t))return {who:'Lauterbach · inszenierter Funk',text:'Ich kann dir keine bestätigte Räumung melden. Zu den Menschen im Stadion liegt mir jetzt keine verlässliche neue Rückmeldung vor.'};
 if(/kabine|passagier|besatzung|rett|eingreif|gegenwehr|an bord/.test(t))return {who:'Lauterbach · inszenierter Funk',text:'Mir liegt keine belastbare Meldung aus der Kabine vor. Ich weiss nicht, ob dort jemand eingreift. Das Schweigen gibt uns darauf keine Antwort.'};
 if(/befehl|schiess|schuss|feuer|freigabe|erlaub|minister|radtke|entschei|genehmig/.test(t))return {who:'Lauterbach · inszenierter Funk',text:elapsed>=85?'Der Nicht-Abschussbefehl gilt weiter. Radtke hat die Frage an den Minister herangetragen. Keine neue Freigabe.':'Ich gebe deine Frage weiter. Radtke ist eingeschaltet, die Frage geht an den Verteidigungsminister. Eine Abschussfreigabe habe ich nicht.'};
 if(/sink|sinkt|tiefer|abwart|zeit|kurs|gefahr/.test(t))return {who:'Lauterbach · inszenierter Funk',text:elapsed>=120?'Deine Meldung über den Sinkflug ist angekommen. Ich habe keine neue Entscheidung. Was im Cockpit der Maschine geschieht, kann ich dir nicht bestätigen.':'Meldung verstanden. Ich habe keine zusätzliche gesicherte Information zur Entwicklung der Lage. Halte Beobachtung und Vermutung auseinander.'};
 if(/angst|familie|sohn|frau|nerv|kann nicht|allein|verantwort/.test(t))return {who:'Lauterbach · inszenierter Funk',text:'Ich höre dich. Ich kann dir die Verantwortung und die Ungewissheit nicht abnehmen. Sage mir, welche konkrete Rückmeldung du brauchst.'};
 return {who:'Lauterbach · inszenierter Funk',text:'Ich höre dich, aber deine konkrete Anfrage ist mir nicht klar. Wen sprichst du an und welche Information brauchst du? Mir liegt weiterhin keine neue Abschussfreigabe vor.'};
}
export function sendRadio(s,text){const message=String(text).trim().slice(0,1200);if(s.ended||s.elapsed>=DURATION||message.length<3||s.pending.length>=3)return false;
 s.log.push({at:s.elapsed,who:'Du · eigener Funktext',text:message});const reply=radioReply(message,s.elapsed);s.pending.push({at:Math.min(DURATION,s.elapsed+7),...reply});return true;}
export function interpretDecision(text){const t=norm(text).trim();if(t.length<6||/[?]/.test(t)||/\b(vielleicht|eventuell|falls|wenn|oder|sollte|wurde|unsicher)\b/.test(t))return null;
 if(/\b(offen|unentschieden)\b|noch nicht entscheiden|keine entscheidung/.test(t))return 'offen';
 const no=/nicht (?:zu )?(?:ab)?schiess|schiesse nicht|schiessen (?:werde ich )?nicht|kein(?:en)? (?:abschuss|schuss)|verzichte auf (?:den )?abschuss|unterlasse (?:den )?abschuss|nicht feuern|feuere nicht|gegen (?:den )?abschuss|halte (?:das )?feuer zuruck/.test(t);
 const yes=/ich (?:werde (?:jetzt )?)?(?:jetzt )?(?:schiesse|schiessen|feuere)|ich entscheide mich fur (?:den )?abschuss|ich werde (?:die maschine |das flugzeug )?abschiessen/.test(t);
 if(no){const rest=t.replace(/ich schiesse nicht|nicht (?:zu )?(?:ab)?schiessen|kein(?:en)? (?:abschuss|schuss)/g,'');if(/aber.*(?:ich schiesse|ich feuere)|doch.*abschuss/.test(rest))return null;return 'nicht';}if(/\b(nicht|kein|keine|keinen|niemals|nie)\b/.test(t))return null;return yes?'schiessen':null;}
